fn history_parameters() -> Vec<Parameter> {
    let mut parameters = super::route_parameters::record_id32();
    parameters.extend([
        p(
            "beforeId",
            "query",
            None,
            i().minimum(num("1")).format("int64"),
        ),
        p(
            "limit",
            "query",
            None,
            i().minimum(num("1"))
                .maximum(num("200"))
                .default_value(serde_json::json!(30)),
        ),
    ]);
    parameters
}

